using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.AlgebraicBoundary;
internal sealed class ConeFiniteBoundaryDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The original principal boundary ideal at arbitrary finite degree.",
        H("Arbitrary-degree entire boundary minima"),
        Blocks(Paragraph(Text("Any nonzero polynomial vanishing on the entire original ambient frontier gives native semialgebraicity. Directly consume exists_homogeneous_minimum and minimum_boundary_ideal on the original coordinate image. This gives a positive minimum degree, a homogeneous squarefree nonzero equation of exactly that degree, and divisibility of every original entire-boundary equation, with no degree or homogeneity restriction on the comparison equation. Both directions of the principal ideal identity are retained.")),
        Paragraph(Text("Every nonzero comparison equation of at most the minimum degree is a scalar multiple of that same generator: divide it by the generator using the actual ideal theorem, then use additivity of total degree in the polynomial domain. The quotient has degree zero and hence is a real constant; nonzero comparison excludes a zero constant. This arbitrary-degree scalar uniqueness uses no interior nonvanishing or hyperbolicity premise.")),
        Paragraph(Text("For every actual factorization of this same nonzero homogeneous generator into f times g, both factors are nonzero and homogeneous at their total degrees, whose sum is the generator degree. The proof works over any coefficient domain and any variable type. Formal scaling sends a polynomial to a one-variable polynomial with its original homogeneous components as coefficients. Fixed-library additivity of highest and lowest nonzero degrees forces each factor's degree range to have width zero. This includes unit and constant factors, all arbitrary degree partitions, and repeated factors of a general homogeneous polynomial; only the separate minimum theorem imposes squarefreeness. degreeExpansion_monomial, degreeExpansion_coeff and degreeExpansion_homogeneous are consumed inside homogeneous_factors, which is consumed in original_finite_boundary_ideal and hence the original public host. The representation, extreme-degree library applications and final assembly supply no independent escape credit.")))));
}
